const int ART_WIDTH[SCALES]={12,20,30,44,60,80,104,132,164,200};
uint8_t rgb(int r,int g,int b){return uint8_t(192+r+4*g+16*b);}
RGB888 colour(uint8_t c){return RGB888((c&3)*85,((c>>2)&3)*85,((c>>4)&3)*85);}
void rect(int x,int y,int x2,int y2,uint8_t c){if(sceneDrawing){x=std::max(viewLeft(),x);x2=std::min(viewRight(),x2);y=std::max(28,y);y2=std::min(191,y2);}if(x2<0||x>639||y2<0||y>199||x2<x||y2<y)return;x=std::max(0,x);x2=std::min(639,x2);y=std::max(0,y);y2=std::min(199,y2);if(rasterActive){rasterRect(x,y,x2-x+1,y2-y+1,c);return;}canvas.setBrushColor(colour(c));canvas.fillRectangle(x,y,x2,y2);}
