void mapPixel(int x,int y,uint8_t c){if(x>=0&&x<64&&y>=0&&y<88)mapPixels[y*64+x]=c;}
void mapLine(int x0,int y0,int x1,int y1,uint8_t c,int radius){int dx=abs(x1-x0),dy=-abs(y1-y0),sx=x0<x1?1:-1,sy=y0<y1?1:-1,err=dx+dy;for(;;){for(int y=-radius;y<=radius;++y)for(int x=-radius;x<=radius;++x)mapPixel(x0+x,y0+y,c);if(x0==x1&&y0==y1)break;int e=2*err;if(e>=dy){err+=dy;x0+=sx;}if(e<=dx){err+=dx;y0+=sy;}}}
