void renderGame(const Input&in){if(race.screen==TITLE){renderTitle();return;}if(race.screen==TITLE_EXIT){renderTitleExit();return;}if(race.screen==CAR_SELECT){renderGarage();return;}if(race.screen==DIFFICULTY_SELECT){renderDifficulty();return;}if(race.screen==NAME_ENTRY){renderName();return;}if(race.screen==HALL_OF_FAME){renderHall(false);return;}if(race.screen==FINISHED||race.screen==GAMEOVER){renderResult();return;}renderRoad();renderOil();renderActors(in);renderGate();renderHUD();}
